def validate_name(value):
    v = value.strip()
    if len(v) == 0:
        return "required"
    if len(v) == 1:
        return "too_short"
    if len(v) > 50:
        return "too_long"
    for ch in v:
        if not (ch.isalpha() or ch in " -'"):
            return "bad_chars"
    return None
